//! The Rust side of ipc-runtime: what code generated by ipc-codegen runs on, and the UDS + MPSC-SHM
//! transport.
//!
//! Always built, pure Rust, for every target (native, wasm, mobile):
//! - [`backend`]: the `Backend` and `AsyncBackend` traits a generated `<Service>Api` and
//!   `<Service>AsyncApi` run over.
//! - [`error`]: the error type generated clients return.
//! - [`host_call_backend`]: a blocking call to a service the host provides.
//! - [`async_host`]: asynchronous instances, whose handlers await their host calls.
//!
//! With the `sockets` feature (on by default), which compiles the C++ runtime:
//! - `IpcServer` and `IpcClient`, picking the transport from the path's suffix (`.sock` → UDS,
//!   `.shm` → MPSC-SHM). See ipc-runtime/cpp/ipc_runtime/c_abi.h for the underlying C ABI.
//! - `process_host_calls`: host calls for a service run as a server process, and `serve_async`,
//!   which serves an asynchronous instance re-entrantly on one thread.
//!
//! A wasm module or a mobile library depends on this crate with `default-features = false`, so its
//! build needs no C++ toolchain.

pub mod async_host;
pub mod backend;
pub mod error;
pub mod host_call_backend;

#[cfg(feature = "sockets")]
pub mod process_host_calls;
#[cfg(feature = "sockets")]
mod transport;
#[cfg(feature = "sockets")]
pub use transport::*;
